<?php
if (!defined('ABSPATH')) exit;
add_action('init',function(){
    if(get_option('bhc_catalog_content_contamination_hygiene_v149')||!function_exists('wc_get_products'))return;
    $updated=0;$rebuilt=0;$quarantined=0;$detached=0;
    $exact_types=['exact_model_page','exact_retailer_page','official_exact_model_page'];
    foreach(wc_get_products(['limit'=>-1,'status'=>['draft','publish','pending','private'],'return'=>'objects']) as $p){
        $id=$p->get_id();$old=$p->get_description();if(strpos($old,'تفال')===false&&strpos($old,'EXPRESS-AIRGLIDE')===false)continue;
        $type=(string)get_post_meta($id,'_bhc_source_type',true);$is_exact=in_array($type,$exact_types,true);$spec_raw=(string)get_post_meta($id,'_bhc_structured_specs',true);$specs=json_decode($spec_raw,true);$has_specs=is_array($specs)&&$specs;
        $lines='';if($has_specs)foreach($specs as $k=>$v){if(is_array($v))$v=implode('، ',$v);$lines.='<li><strong>'.esc_html($k).':</strong> '.esc_html((string)$v).'</li>';}
        $name=$p->get_name();$url=(string)get_post_meta($id,'_bhc_source_url',true);$source_link=$url?'<p>منبع فعلی رکورد: <a href="'.esc_url($url).'" target="_blank" rel="nofollow noopener">مشاهده منبع</a></p>':'';
        if($is_exact&&$has_specs){$desc='<p>'.esc_html($name).' بر اساس منبع مدل‌محور ثبت شده است. متن قبلی نامرتبط بود و در این فاز حذف و با محتوای مطابق مدل جایگزین شد. قیمت درج نشده و وضعیت کالا ناموجود است.</p><h3>درباره محصول</h3><p>این صفحه فقط اطلاعاتی را نگه می‌دارد که در رکورد ساختاریافته و منبع مدل ثبت شده‌اند؛ موارد اعلام‌نشده حدس زده نشده‌اند.</p><h3>اطلاعات فنی</h3><ul>'.$lines.'</ul><h3>راهنمای انتخاب و کنترل پیش از عرضه</h3><p>کد کامل مدل، رنگ، نسخه بازار، ابعاد نصب، اقلام همراه، اصالت و گارانتی باید پیش از عرضه با برچسب دستگاه و نمایندگی مجاز تطبیق داده شود.</p><h3>گارانتی و ارسال</h3><p>گارانتی و خدمات پس از فروش هنگام تأمین باید تأیید شود. ارسال پس از تأیید موجودی، اصالت و شرایط نصب انجام می‌شود.</p><h3>پرسش‌های متداول</h3><p><strong>آیا کالا موجود است؟</strong><br>خیر، ناموجود است.</p><p><strong>آیا قیمت درج شده؟</strong><br>خیر.</p>'.$source_link; $rebuilt++;}
        else{$desc='<p>'.esc_html($name).' در کاتالوگ به‌صورت ناموجود و غیرقابل انتشار نگهداری می‌شود. متن قبلی این رکورد با محصول دیگری همخوانی نداشت و حذف شد.</p><h3>درباره محصول</h3><p>منبع دقیق مدل، مشخصات فنی قابل استناد و تصویر اختصاصی هنوز تکمیل نشده است؛ هیچ ویژگی فنی از روی نام یا شباهت ظاهری حدس زده نمی‌شود.</p><h3>اطلاعات فنی</h3><p>پس از یافتن صفحه دقیق مدل یا سند سازنده تکمیل خواهد شد.</p><h3>وضعیت کاتالوگ</h3><p>این رکورد فعلاً برای بررسی منبع دقیق، تطبیق برند و تولید تصویر اختصاصی قرنطینه شده است و نباید منتشر شود.</p><h3>گارانتی و ارسال</h3><p>تا زمان تأیید مدل، اصالت، موجودی و نمایندگی، گارانتی و ارسال قابل اعلام نیست.</p><h3>پرسش‌های متداول</h3><p><strong>آیا کالا موجود است؟</strong><br>خیر، ناموجود است.</p><p><strong>آیا مشخصات نهایی است؟</strong><br>خیر، منبع دقیق هنوز تأیید نشده است.</p>';if($url){update_post_meta($id,'_bhc_legacy_source_url',$url);delete_post_meta($id,'_bhc_source_url');}update_post_meta($id,'_bhc_source_type','legacy_needs_exact');update_post_meta($id,'_bhc_verification_status','needs_source');update_post_meta($id,'_bhc_catalog_quality_state','reference_needs_verification');update_post_meta($id,'_bhc_image_generation_status','awaiting_product_reference');delete_post_meta($id,'_bhc_image_reference_url');delete_post_meta($id,'_bhc_image_reference_evidence');delete_post_meta($id,'_bhc_image_reference_checked_at');if(has_post_thumbnail($id)&&get_post_meta($id,'_bhc_image_status',true)!=='generated_4k_transparent'){delete_post_thumbnail($id);$detached++;}$quarantined++;}
        $p->set_description($desc);$p->set_short_description($name.' · ناموجود · وضعیت کاتالوگ: '.($is_exact?'نیازمند بازبینی نهایی':'نیازمند منبع دقیق'));$p->set_status('draft');$p->set_catalog_visibility('hidden');$p->set_stock_status('outofstock');$p->save();$updated++;
    }
    update_option('bhc_catalog_content_contamination_hygiene_v149',['updated'=>$updated,'rebuilt'=>$rebuilt,'quarantined'=>$quarantined,'detached'=>$detached,'at'=>current_time('mysql')],false);
},149);
